package com.cpf.starter.notification;import java.time.Clock;import org.springframework.beans.factory.ObjectProvider;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.context.annotation.Bean;import org.springframework.jdbc.core.JdbcTemplate;
@AutoConfiguration public class CpfNotificationAutoConfiguration {@Bean JdbcCpfNotificationOutbox cpfNotificationOutbox(JdbcTemplate j){return new JdbcCpfNotificationOutbox(j);}@Bean CpfNotificationPreferencePolicy cpfNotificationPreferencePolicy(){return new CpfNotificationPreferencePolicy();}@Bean CpfNotificationWorker cpfNotificationWorker(JdbcCpfNotificationOutbox o,ObjectProvider<CpfNotificationProvider> p,CpfNotificationPreferencePolicy policy){return new CpfNotificationWorker(o,p.orderedStream().toList(),policy,Clock.systemUTC());}}
